/* ============================================================
 * 群小说网 (www.qunxs.com) 小说书源 jsLib —— 纯 ES5（Rhino 兼容）
 * 站点形态：Laravel HTML 服务端渲染
 *   详情  /xiaoshuo_{bid}.html
 *   目录  /txt/{bid}.html、/txt/{bid}_{p}.html（每页 100 章）
 *   正文  /txt/{bid}/{cid}.html、/txt/{bid}/{cid}_{p}.html
 *         翻页地址藏在 dean packer 混淆的 eval 块里，需运行时解码
 *         章节末页无 eval 块（"下一页"直接指下一章，绝不能跟）
 * 水印：句内注入「(<a>…</a>)来…看最新章节…完整章节(ｑｕｎｘｓ)•(com)」
 * ============================================================ */

/* ---------------- 基础工具（与通用 jsLib 同实现） ---------------- */
function kbTrim(s) {
    return String(s === null || s === undefined ? '' : s).replace(/^[\s\u00a0\u3000]+|[\s\u00a0\u3000]+$/g, '');
}

function kbUnescape(s) {
    var t = String(s === null || s === undefined ? '' : s);
    t = t.replace(/&nbsp;/gi, ' ').replace(/&ensp;/gi, ' ').replace(/&emsp;/gi, '\u3000');
    t = t.replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"');
    t = t.replace(/&apos;/gi, "'").replace(/&#39;/g, "'");
    t = t.replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
    t = t.replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); });
    t = t.replace(/&amp;/gi, '&');
    return t;
}

function kbDate(v) {
    if (v === null || v === undefined || v === '') return '';
    var m = String(v).match(/(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})/);
    if (m) return m[1] + '-' + (m[2].length < 2 ? '0' + m[2] : m[2]) + '-' + (m[3].length < 2 ? '0' + m[3] : m[3]);
    return '';
}

/* ---------------- 水印净化（句内注入，不能按行丢） ----------------
 * 实测三种变体（均在句中/句尾插入）：
 *   ⑿(<a href="…ｑｕｎｘｓ．ｃｏｍ">[(ｑｕｎｘｓ．ｃｏｍ)]</a>)◀来⑿群小？♧说网⑿？♧看最新章节？♧完整章节⑿(ｑｕｎｘｓ)•(com)
 *   ⒏(<a href="…">[群小说@▧网]</a>)⒏⅕来⒏群小说@▧网⒏@▧看最新章节@▧完整章节⒏(ｑｕｎｘｓ)•(com)
 *   ✏(<a href="…">[(ｑｕｎｘｓ．ｃｏｍ)]</a>)⊕来✏群？♧小说网✏？♧看最新章节？♧完整章节✏(ｑｕｎｘｓ)•(com)
 * 步骤：① 摘含水印标记的 <a> 整块 ② 删噪声符号 ③ 删水印短语骨架 ④ 删残留域名
 */
function qsClean(s) {
    var t = String(s === null || s === undefined ? '' : s);
    // ① <a> 锚点：配对的整块摘除；未闭合的开标签也剥掉（水印 href 会被混淆）
    t = t.replace(/<a[^>]*>[\s\S]*?<\/a>/gi, '');
    t = t.replace(/<a[^>]*>/gi, '');
    // ② 噪声装饰符号（带圈数字/几何形状/手写符号/卍 等水印专用字符，正文几乎不用）
    t = t.replace(/[\u2460-\u24ff\u2150-\u215f\u2500-\u25ff\u2200-\u22ff\u2600-\u27bf\u2102\u2117\u2121\u534d\u5350]/gi, '');
    // ③′ 更新提醒句（骨架 + 有界窗口）：…提醒您《书名》第一时间在…更新…看最新章节…完整章节…
    t = t.replace(/[^。！？\n]{0,40}提醒您[\s\S]{0,200}?完整章节[\s\S]{0,15}?/g, '');
    // ③ 水印域名全角拉丁归一（ｑｕｎｘｓ ｃｏｍ ． → 半角；仅限这几个字符，不动中文标点）
    t = t.replace(/[ｑｕｎｘｓｃｏｍ＠]/g, function (c) { return String.fromCharCode(c.charCodeAt(0) - 0xFEE0); });
    t = t.replace(/．/g, '.');
    // ④ 站名/域名括块（锚点被剥后留下的纯文本块，[()] 括号形态不定）
    t = t.replace(/[\[(（]\s*群[^\n。！？]{0,4}网\s*[\])）]/g, '');
    t = t.replace(/[\[(（]\s*qunxs[.．_＠@\s]{0,4}com\s*[\])）]/gi, '');
    t = t.replace(/[（(]\s*qunxs\s*[)）]\s*[•·]?\s*[（(]\s*com\s*[）)]/gi, '');
    t = t.replace(/qunxs[.．_＠@\s]{0,3}com/gi, '');
    // ⑤ 水印短语骨架（骨架词：看最新章节/完整章节，正文不会出现）
    //   WS = 水印间隔符（随机符号字，不含字母数字与汉字）；SW = 间隔符或站名词片段
    var WS = '[^0-9A-Za-z\\u4e00-\\u9fa5\\n]';
    var SW = '(?:' + WS + '|群|小说|小说网|小|说|网)';
    //   a. 带引导"来"（最常见）：来…群…看最新章节…完整章节（首个间隔不含"来"，贴水印自己的"来"起切）
    t = t.replace(new RegExp('来' + WS + '{0,4}群' + SW + '{0,8}看最新章节' + WS + '{0,6}完整章节', 'g'), '');
    //   b. 其他引导（域名/网址/记住/裸符号串）：…看最新章节…完整章节
    t = t.replace(new RegExp('(?:' + SW + '|域名|网址|地址|记住|网站){1,16}看最新章节' + WS + '{0,6}完整章节', 'g'), '');
    //   c. 悬在句尾的裸站名残渣：群(小)说网…，/。
    t = t.replace(new RegExp('群' + WS + '{0,2}小' + WS + '{0,2}说?' + WS + '{0,2}网(?=[，,。！？\\n]|$)', 'g'), '');
    // ⑥ 清尾：空括号、残留标签、首部残渣；尾部只剥水印符号（不动正文的句读）
    t = t.replace(/[(（\[{]\s*[)\]}\t]/g, '');
    t = t.replace(/<[^>]+>/g, '');
    t = t.replace(/^[、。．，,_＠@*#$%•·…℡ℂ℗卍卐Θ]{1,6}/g, '');
    t = t.replace(/[_＠@*#$%℡ℂ℗卍卐Θ]{1,6}$/g, '');
    t = t.replace(/\s{2,}/g, ' ');
    return kbTrim(t);
}

/* 整段都是水印广告句的判定（qClean 后仍残留骨架词 → 弃整段） */
function qsIsAdLine(s) {
    return /看最新章节|完整章节|提醒您|全网首发|记住[^。！？\n]{0,8}(?:域名|网址|群|小说)|qunxs|ｑｕｎｘｓ/i.test(String(s || ''));
}

/* ---------------- 正文 ---------------- */
function qsParasOf(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/<div\s+id="booktxt">([\s\S]*?)<div\s+id="nr_page"/i);
    if (!m) m = t.match(/<div\s+id="booktxt">([\s\S]*?)<\/div>\s*<\/div>/i);
    if (!m) return [];
    var blk = m[1], out = [], re = /<p[^>]*>([\s\S]*?)<\/p>/gi, mm;
    while ((mm = re.exec(blk))) {
        var line = qsClean(mm[1]);                  // 整块原样交给 qsClean（含 <a> 水印锚点）
        if (line && line.length > 1 && !qsIsAdLine(line)) out.push(line);
    }
    return out;
}

function qsContent(html) {
    var ps = qsParasOf(html);
    if (!ps.length) return '△ 正文获取失败';
    return ps.join('\n');
}

/* ---------------- 正文翻页：解码 dean packer 混淆的 eval 块 ----------------
 * 原文形态：
 *   }('4 2 = "3"+"5/0.1";',62,6,'8488079_2|html|u6afecdb0338d1|/txt/|var|14014'.split('|'),0,{})
 * 解码即把模板里的 \b\w+\b 按词表下标还原 → var x = "/txt/14014/8488079_2.html";
 * 仅当本页确有同章下一页时返回 URL；章节末页无 eval 块、h1 页码到顶，均返回 ''。
 */
function qIdx(tok, base) {
    var r = 0, i, c, v;
    for (i = 0; i < tok.length; i++) {
        c = tok.charAt(i);
        if (c >= '0' && c <= '9') v = c.charCodeAt(0) - 48;
        else if (c >= 'a' && c <= 'z') v = c.charCodeAt(0) - 87;
        else v = c.charCodeAt(0) - 29;   // 'A'..'Z' → 36..61
        r = r * base + v;
    }
    return r;
}

function qsNext(html, baseUrl) {
    var t = String(html === null || html === undefined ? '' : html);
    var u = String(baseUrl === null || baseUrl === undefined ? '' : baseUrl);
    if (!t || !u) return '';
    // 守卫 1：h1 页码 (cur/total)，到顶不再翻
    var pm = t.match(/[(（]\s*(\d+)\s*\/\s*(\d+)\s*[)）]\s*<\/h1>/);
    if (pm) {
        var cur = parseInt(pm[1], 10), tot = parseInt(pm[2], 10);
        if (tot && cur >= tot) return '';
    }
    // 找 eval packer 块
    var m = t.match(/\}\('([^{']*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'([^']*)'\s*\.\s*split\s*\(\s*'\|'\s*\)/);
    if (!m) return '';
    var words = m[4].split('|'), tpl = m[1], base = parseInt(m[2], 10) || 62;
    var dec = tpl.replace(/\b\w+\b/g, function (tok) {
        var i = qIdx(tok, base);
        return words[i] === undefined ? tok : words[i];
    });
    var vm2 = dec.match(/=\s*((?:"[^"]*"\s*\+\s*)*"[^"]*")/);
    if (!vm2) return '';
    var segs = vm2[1].match(/"([^"]*)"/g) || [];   // 值可能是多段字符串拼接
    var path = '', si;
    for (si = 0; si < segs.length; si++) path += segs[si].slice(1, -1);
    if (!path) return '';
    // 守卫 2：下一页必须仍是本章（同章节 id + 同书 id）
    var curM = u.match(/\/txt\/(\d+)\/(\d+)(?:_(\d+))?\.html/);
    var nxtM = path.match(/\/txt\/(\d+)\/(\d+)(?:_(\d+))?\.html/);
    if (curM && nxtM) {
        if (curM[1] !== nxtM[1] || curM[2] !== nxtM[2]) return '';   // 书号/章号变了 = 指向下一章，拒跟
        if (nxtM[3] && curM[3] && parseInt(nxtM[3], 10) <= parseInt(curM[3], 10)) return '';
    }
    var host = u.match(/^https?:\/\/[^\/]+/);
    if (!host) return '';
    return path.charAt(0) === '/' ? host[0] + path : host[0] + '/' + path;
}

/* ---------------- 详情页 ---------------- */
function qsTocUrl(html, baseUrl) {
    var h = String(html === null || html === undefined ? '' : html);
    var u = String(baseUrl === null || baseUrl === undefined ? '' : baseUrl);
    var m = h.match(/href="(\/txt\/\d+\.html)"/);            // 详情页"全部章节目录"锚点
    if (!m) {
        var b = u.match(/xiaoshuo_(\d+)/) || h.match(/xiaoshuo_(\d+)/);
        if (b) m = [null, '/txt/' + b[1] + '.html'];
    }
    if (!m) return u;                                        // 兜底：目录规则回退到详情页本身
    var host = u.match(/^https?:\/\/[^\/]+/);
    return host ? host[0] + m[1] : m[1];
}

function qsCleanChip(v) {
    var t = String(v === null || v === undefined ? '' : v);
    t = t.replace(/<[^>]+>/g, '');
    t = t.replace(/[\[\]【】()（）「」『』《》]/g, '');
    t = kbTrim(t.replace(/\s+/g, ' '));
    return t;
}

function qsKind(html) {
    var t = String(html === null || html === undefined ? '' : html), chips = [];
    var top = t.match(/class="con_top"([\s\S]*?)<\/div>/);
    if (top) {
        var as = top[1].match(/<a[^>]*>([^<]*)<\/a>/g) || [];
        if (as.length > 1) {
            var c = qsCleanChip(String(as[1]).replace(/<[^>]+>/g, ''));
            if (c) chips.push(c);
        }
    }
    var st = t.match(/状态[:：]\s*([^\s<]{1,6})/);
    if (st) {
        var s2 = st[1].indexOf('完结') > -1 ? '完结' : '连载';
        chips.push(s2);
    } else if (/ \| \s*连载/.test(t)) chips.push('连载');
    else if (/ \| \s*完结/.test(t)) chips.push('完结');
    var wc = t.match(/([\d.]+)\s*万字/);
    if (wc) chips.push(wc[1] + '万字');
    return chips.join(',');
}

function qsWord(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/字数[:：]\s*([\d.]+\s*万字?)/) || t.match(/([\d.]+)\s*万字/);
    return m ? m[1].replace(/\s+/g, '') : '';
}

function qsIntro(html) {
    var t = String(html === null || html === undefined ? '' : html);
    var m = t.match(/<div\s+id="intro"([\s\S]*?)<\/div>/i);
    if (m) t = m[1];
    t = t.replace(/<[^>]+>/g, '\n');
    t = kbUnescape(t);
    t = t.replace(/\r\n?/g, '\n');
    var lines = t.split('\n'), out = [], i, l;
    for (i = 0; i < lines.length; i++) {
        l = qsClean(lines[i]);
        if (!l || l.length < 2) continue;
        out.push('\u3000\u3000' + l);           // 简介区不自动缩进，手加两个全角空格
    }
    return out.join('\n');
}

/* ---------------- 列表字段（搜索/发现/详情通用） ---------------- */
function qsListIntro(v) {
    return qsClean(v);
}
